            { "markPrice", null },
            { "notional", null },
            { "leverage", null },
            { "collateral", null },
            { "initialMargin", null },
            { "initialMarginPercentage", null },
            { "maintenanceMargin", null },
            { "maintenanceMarginPercentage", null },
            { "unrealizedPnl", null },
            { "liquidationPrice", null },
            { "marginMode", null },
            { "marginRatio", null },
            { "percentage", null },
        });
    }

